/* 跑 72MHz 的标准配置（SystemInit 已做，这里是说明） */
FLASH_PrefetchBufferCmd(FLASH_PrefetchBuffer_Enable);
FLASH_SetLatency(FLASH_Latency_2);        /* 48~72MHz 必须 2 个等待周期 */

/* 然后才能把 PLL 切到 72MHz */
RCC_PLLConfig(RCC_PLLSource_HSE_Div1, RCC_PLLMul_9);

/* SystemInit 里的标准写法：先预取，再设等待周期，最后切 PLL */
FLASH_PrefetchBufferCmd(FLASH_PrefetchBuffer_Enable);
FLASH_SetLatency(FLASH_Latency_2);

/* 写入 Flash 的完整流程（以 C8T6 为例，页大小 1KB） */
#define FLASH_SAVE_ADDR  0x0800FC00   /* 最后一页，避开程序区 */

uint16_t data = 0x1234;

FLASH_Unlock();                          /* 1. 解锁 */
FLASH_ClearFlag(FLASH_FLAG_EOP | FLASH_FLAG_PGERR | FLASH_FLAG_WRPRTERR);  /* 2. 清标志 */

FLASH_Status st = FLASH_ErasePage(FLASH_SAVE_ADDR);   /* 3. 先擦除整页 */
if (st == FLASH_COMPLETE)
{
  st = FLASH_ProgramHalfWord(FLASH_SAVE_ADDR, data);  /* 4. 再写 */
}

FLASH_Lock();                            /* 5. 用完立刻上锁 */

FLASH_Unlock();
FLASH_ClearFlag(FLASH_FLAG_EOP | FLASH_FLAG_PGERR | FLASH_FLAG_WRPRTERR);
FLASH_ErasePage(FLASH_SAVE_ADDR);
FLASH_ProgramHalfWord(FLASH_SAVE_ADDR, data);
FLASH_Lock();      /* 用完立即上锁 */

/* 擦除第 64 页（C8T6 共 64 页，每页 1KB） */
#define PAGE64_ADDR  0x0800FC00   /* 0x08000000 + 63*1024 */

FLASH_Unlock();
FLASH_ClearFlag(FLASH_FLAG_EOP | FLASH_FLAG_PGERR | FLASH_FLAG_WRPRTERR);

FLASH_Status status = FLASH_ErasePage(PAGE64_ADDR);
if (status != FLASH_COMPLETE)
{
  /* 擦除失败：多为忘记 Unlock 或该页被写保护 */
}

FLASH_Lock();

/* 修改用户选项字节的标准流程：先擦除再写回 */
FLASH_Unlock();
FLASH_EraseOptionBytes();
FLASH_UserOptionByteConfig(OB_IWDG_SW, OB_STOP_NoRST, OB_STDBY_NoRST);
FLASH_Lock();

/* 选项字节的修改要等复位后才生效 */

/* 往已擦除的页写 3 个 32 位数据 */
#define BASE_ADDR  0x0800FC00
uint32_t values[3] = {0x11223344, 0x55667788, 0x99AABBCC};

FLASH_Unlock();
FLASH_ClearFlag(FLASH_FLAG_EOP | FLASH_FLAG_PGERR | FLASH_FLAG_WRPRTERR);
FLASH_ErasePage(BASE_ADDR);

for (i = 0; i < 3; i++)
{
  /* 每次写之前清标志；地址必须 4 字节对齐 */
  FLASH_ClearFlag(FLASH_FLAG_EOP | FLASH_FLAG_PGERR | FLASH_FLAG_WRPRTERR);
  if (FLASH_ProgramWord(BASE_ADDR + i * 4, values[i]) != FLASH_COMPLETE)
  {
    break;   /* 写入失败 */
  }
}

FLASH_Lock();

/* 保存一组 16 位标定参数 */
#define PARAM_ADDR  0x0800F800
uint16_t params[4] = {100, 200, 300, 400};

FLASH_Unlock();
FLASH_ClearFlag(FLASH_FLAG_EOP | FLASH_FLAG_PGERR | FLASH_FLAG_WRPRTERR);
FLASH_ErasePage(PARAM_ADDR);

for (i = 0; i < 4; i++)
{
  FLASH_ClearFlag(FLASH_FLAG_EOP | FLASH_FLAG_PGERR | FLASH_FLAG_WRPRTERR);
  FLASH_ProgramHalfWord(PARAM_ADDR + i * 2, params[i]);
}

FLASH_Lock();

/* 读取时直接按指针访问即可，Flash 可随机读 */
uint16_t v = *(volatile uint16_t *)(PARAM_ADDR + 2);

/* 往选项字节数据区写产品编号 */
FLASH_Unlock();
FLASH_EraseOptionBytes();                                  /* 必须整块擦除后才能改 */
FLASH_ProgramOptionByteData(0x1FFFF804, 0x5A);             /* Data0 */
FLASH_ProgramOptionByteData(0x1FFFF806, 0xA5);             /* Data1 */
FLASH_Lock();

/* 复位后生效，读取方式：*(uint8_t*)0x1FFFF804 */

/* 保护前 4 页（对应 C8T6 的 0x08000000~0x08000FFF） */
FLASH_Unlock();
FLASH_EraseOptionBytes();                       /* 必须先擦除选项字节 */
FLASH_EnableWriteProtection(FLASH_WriteProtection_0);
FLASH_Lock();

/* 复位后生效；生效后这几页无法擦写，只能用 SWD 全片擦除解除 */

/* 开启读保护：防止固件被读出 */
FLASH_Unlock();
FLASH_ReadOutProtection(ENABLE);
FLASH_Lock();
/* 复位后生效 */

/* 关闭读保护：注意！会连同整个 Flash 一起被硬件擦除 */
FLASH_Unlock();
FLASH_ReadOutProtection(DISABLE);   /* 全片数据在此刻丢失 */
FLASH_Lock();
/* 之后需要重新烧录程序 */

/* 把看门狗改成软件模式，停止/待机模式不复位 */
FLASH_Unlock();
FLASH_EraseOptionBytes();                                    /* 必须先擦除 */
FLASH_UserOptionByteConfig(OB_IWDG_SW, OB_STOP_NoRST, OB_STDBY_NoRST);
FLASH_Lock();

/* 选项字节复位后才生效，写完要重启一次 */
NVIC_SystemReset();

uint32_t ob = FLASH_GetUserOptionByte();

if ((ob & 0x01) == 0)
{
  /* bit0 = 0 表示硬件看门狗已使能，上电即启动，必须及时喂狗 */
}
if ((ob & 0x02) == 0)
{
  /* 进入停止模式会复位 */
}

if (FLASH_GetReadOutProtectionStatus() == SET)
{
  /* 已开启读保护，调试器读不出 Flash */
}

if (FLASH_GetPrefetchBufferStatus() == RESET)
{
  /* 72MHz 下应使能预取，否则取指效率低 */
  FLASH_PrefetchBufferCmd(FLASH_PrefetchBuffer_Enable);
}

NVIC_InitTypeDef NVIC_InitStructure;

NVIC_InitStructure.NVIC_IRQChannel = FLASH_IRQn;
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 2;
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 0;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);

FLASH_ITConfig(FLASH_IT_EOP, ENABLE);

/* 擦除后检查是否出错 */
FLASH_ErasePage(0x0800FC00);
while (FLASH_GetFlagStatus(FLASH_FLAG_BSY) == SET);   /* 等忙结束 */

if (FLASH_GetFlagStatus(FLASH_FLAG_PGERR) == SET)
{
  /* 编程错误：目标没擦除 */
}
if (FLASH_GetFlagStatus(FLASH_FLAG_WRPRTERR) == SET)
{
  /* 写保护错误：多半是忘了 FLASH_Unlock */
}

FLASH_ClearFlag(FLASH_FLAG_EOP | FLASH_FLAG_PGERR | FLASH_FLAG_WRPRTERR);

/* 标准写入流程：解锁 → 清标志 → 擦除 → 写 → 上锁 */
FLASH_Unlock();
FLASH_ClearFlag(FLASH_FLAG_EOP | FLASH_FLAG_PGERR | FLASH_FLAG_WRPRTERR);

FLASH_ErasePage(0x0800FC00);

for (i = 0; i < len; i++)
{
  /* 每次写之前再清一次，避免上一次的错误标志干扰 */
  FLASH_ClearFlag(FLASH_FLAG_EOP | FLASH_FLAG_PGERR | FLASH_FLAG_WRPRTERR);
  if (FLASH_ProgramHalfWord(0x0800FC00 + i * 2, buf[i]) != FLASH_COMPLETE)
  {
    break;   /* 写入失败 */
  }
}

FLASH_Lock();

FLASH_Status st = FLASH_GetStatus();
switch (st)
{
  case FLASH_BUSY:        /* 还在忙，继续等 */  break;
  case FLASH_ERROR_PG:    /* 目标没擦除或地址非法 */ break;
  case FLASH_ERROR_WRP:   /* 忘了 Unlock 或该页被写保护 */ break;
  case FLASH_COMPLETE:    /* 完成 */ break;
  default: break;
}

/* 自己操作寄存器后的等待写法 */
FLASH_Status status;
/* ... 发起擦除 ... */
status = FLASH_WaitForLastOperation(0x000B0000);
if (status != FLASH_COMPLETE)
{
  /* 处理错误：PG 通常是没擦除，WRP 通常是 forgetting Unlock */
}

/* 只有 XL 大容量型号才有 Bank2；C8T6 调它没有效果 */
#if defined(STM32F10X_XL)
FLASH_UnlockBank2();
#endif
